## Hook de Traducción

```typescript
// hooks/useTranslation.ts
import { useRouter } from 'next/router'
import { useState, useEffect } from 'react'

export function useTranslation(namespace = 'common') {
  const { locale = 'es' } = useRouter()
  const [translations, setTranslations] = useState({})

  useEffect(() => {
    import(`../public/locales/${locale}/${namespace}.json`)
      .then(module => setTranslations(module.default))
  }, [locale, namespace])

  const t = (key: string, variables?: Record<string, any>) => {
    const keys = key.split('.')
    let value = translations

    for (const k of keys) {
      value = value?.[k]
    }

    if (typeof value === 'string' && variables) {
      return value.replace(/{{(\w+)}}/g, (match, variable) => {
        return variables[variable] || match
      })
    }

    return value || key
  }

  return { t, locale }
}
```

## Componente con i18n

```tsx
// components/BlogPost.tsx
import { useTranslation } from '@/hooks/useTranslation'
import { formatDate } from '@/utils/date'

interface BlogPostProps {
  post: {
    title: string
    excerpt: string
    author: string
    publishedAt: string
  }
}

export default function BlogPost({ post }: BlogPostProps) {
  const { t, locale } = useTranslation()

  return (
    <article className="bg-white p-6 rounded-lg shadow">
      <h2 className="text-2xl font-bold mb-2">{post.title}</h2>
      <p className="text-gray-600 mb-4">{post.excerpt}</p>

      <div className="flex justify-between items-center text-sm text-gray-500">
        <span>
          {t('post.author', { name: post.author })}
        </span>
        <span>
          {t('post.publishedOn', { 
            date: formatDate(post.publishedAt, locale) 
          })}
        </span>
      </div>

      <button className="mt-4 text-blue-600 hover:underline">
        {t('post.readMore')}
      </button>
    </article>
  )
}
```

## Selector de Idioma

```tsx
// components/LanguageSelector.tsx
import { useRouter } from 'next/router'

export default function LanguageSelector() {
  const router = useRouter()
  const { locale, locales, asPath } = router

  const changeLanguage = (newLocale: string) => {
    router.push(asPath, asPath, { locale: newLocale })
  }

  return (
    <select 
      value={locale} 
      onChange={(e) => changeLanguage(e.target.value)}
      className="p-2 border rounded"
    >
      {locales?.map((loc) => (
        <option key={loc} value={loc}>
          {loc.toUpperCase()}
        </option>
      ))}
    </select>
  )
}
```

## Conclusión

La i18n en Next.js es straightforward y permite crear aplicaciones verdaderamente globales con excelente UX.

# Seguridad en Aplicaciones Next.js

La seguridad debe ser una prioridad desde el primer día de desarrollo de cualquier aplicación web.

## Content Security Policy (CSP)

```javascript
// next.config.js
const ContentSecurityPolicy = `
  default-src 'self';
  script-src 'self' 'unsafe-eval' 'unsafe-inline';
  style-src 'self' 'unsafe-inline';
  img-src 'self' blob: data:;
  font-src 'self';
  object-src 'none';
  base-uri 'self';
  form-action 'self';
  frame-ancestors 'none';
  upgrade-insecure-requests;
`

const securityHeaders = [
  {
    key: 'Content-Security-Policy',
    value: ContentSecurityPolicy.replace(/\s{2,}/g, ' ').trim()
  },
  {
    key: 'Referrer-Policy',
    value: 'origin-when-cross-origin'
  },
  {
    key: 'X-Frame-Options',
    value: 'DENY'
  },
  {
    key: 'X-Content-Type-Options',
    value: 'nosniff'
  },
  {
    key: 'X-DNS-Prefetch-Control',
    value: 'false'
  }
]

module.exports = {
  async headers() {
    return [
      {
        source: '/(.*)',
        headers: securityHeaders
      }
    ]
  }
}
```

## Autenticación y Autorización

```typescript
// lib/auth.ts
import { sign, verify } from 'jsonwebtoken'
import bcrypt from 'bcryptjs'

const JWT_SECRET = process.env.JWT_SECRET!

export async function hashPassword(password: string) {
  return bcrypt.hash(password, 12)
}

export async function validatePassword(password: string, hash: string) {
  return bcrypt.compare(password, hash)
}

export function generateToken(userId: string) {
  return sign({ userId }, JWT_SECRET, { expiresIn: '7d' })
}

export function verifyToken(token: string) {
  try {
    return verify(token, JWT_SECRET) as { userId: string }
  } catch {
    return null
  }
}
```

## Middleware de Seguridad

```typescript
// middleware.ts
import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'
import { verifyToken } from './lib/auth'

export function middleware(request: NextRequest) {
  // Rate limiting básico
  const ip = request.ip ?? '127.0.0.1'
  const now = Date.now()
  const windowMs = 15 * 60 * 1000 // 15 minutos
  const maxRequests = 100

  // Aquí implementarías la lógica de rate limiting
  // usando una base de datos o cache como Redis

  // Protección de rutas autenticadas
  if (request.nextUrl.pathname.startsWith('/admin')) {
    const token = request.cookies.get('auth-token')?.value

    if (!token || !verifyToken(token)) {
      return NextResponse.redirect(new URL('/login', request.url))
    }
  }

  // Validación CSRF para formularios
  if (request.method === 'POST') {
    const csrfToken = request.headers.get('x-csrf-token')
    const sessionToken = request.cookies.get('csrf-token')?.value

    if (!csrfToken || csrfToken !== sessionToken) {
      return new NextResponse('Forbidden', { status: 403 })
    }
  }

  return NextResponse.next()
}

export const config = {
  matcher: ['/((?!api|_next/static|_next/image|favicon.ico).*)'],
}
```

## Validación de Entrada

```typescript
// utils/validation.ts
import { z } from 'zod'

export const UserSchema = z.object({
  email: z.string().email().max(100),
  password: z.string().min(8).max(100).regex(
    /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/,
    'Password must contain at least one uppercase, one lowercase, one number and one special character'
  ),
  name: z.string().min(2).max(50).regex(/^[a-zA-Z\s]+$/, 'Name can only contain letters and spaces')
})

export const sanitizeInput = (input: string): string => {
  return input
    .trim()
    .replace(/[<>"'&]/g, (char) => {
      const entities: Record<string, string> = {
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#x27;',
        '&': '&amp;'
      }
      return entities[char] || char
    })
}
```

## API Routes Seguras

```typescript
// pages/api/users.ts
import { NextApiRequest, NextApiResponse } from 'next'
import { UserSchema, sanitizeInput } from '@/utils/validation'
import { hashPassword } from '@/lib/auth'
import rateLimit from '@/lib/rate-limit'

const limiter = rateLimit({
  interval: 60 * 1000, // 1 minuto
  uniqueTokenPerInterval: 500 // límite de 500 usuarios únicos por minuto
})

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  try {
    await limiter.check(res, 10, 'CACHE_TOKEN') // 10 requests por minuto
  } catch {
    return res.status(429).json({ error: 'Rate limit exceeded' })
  }

  if (req.method === 'POST') {
    try {
      // Validar datos de entrada
      const validatedData = UserSchema.parse(req.body)

      // Sanitizar strings
      const sanitizedData = {
        ...validatedData,
        name: sanitizeInput(validatedData.name),
        email: sanitizeInput(validatedData.email.toLowerCase())
      }

      // Hash password
      const hashedPassword = await hashPassword(sanitizedData.password)

      // Crear usuario (implementar lógica de DB)
      const user = await createUser({
        ...sanitizedData,
        password: hashedPassword
      })

      // No devolver password en respuesta
      const { password, ...userWithoutPassword } = user

      res.status(201).json(userWithoutPassword)
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: error.errors })
      }
      res.status(500).json({ error: 'Internal server error' })
    }
  } else {
    res.status(405).json({ error: 'Method not allowed' })
  }
}
```

## Conclusión

La seguridad es un proceso continuo que requiere atención constante y actualizaciones regulares.
